const start = performance.now();
const at = () => `${Math.round(performance.now() - start)} ms`;
// Stands in for a click 10 ms after the export starts
setTimeout(() => console.log(`click handled at ${at()}`), 10);

function sumOfRoots(n) {
  return new Promise((resolve) => {
    let total = 0;
    for (let i = 0; i < n; i++) total += Math.sqrt(i);
    resolve(total);
  });
}

async function exportReport() {
  await sumOfRoots(300_000_000);
  console.log(`report ready at ${at()}`);
}

exportReport();
console.log(`exportReport() returned at ${at()}`);
// exportReport() returned at 662 ms
// report ready at 662 ms
